"""Portable pure mapping controls. Physical rosters below are explicitly synthetic.
Only semantic source-contract paths/bytes/hashes are embedded; no private runtime
receipts or original physical metadata. Two immutable historical digest results
are mocked for the complete-schema control. Physical revalidate is tested separately
on genuinely captured temporary files; it is never patched for those controls.
"""
import unittest,copy,json,base64,zlib,tempfile,pathlib,os,hashlib,subprocess
from unittest.mock import patch
import mapping_profile as m
SEMANTIC_BASELINE_B64=''
class Mapping(unittest.TestCase):
 def setUp(self):
  self.blocks=[]
  for obj,name in[(subprocess,'Popen'),(os,'execve'),(os,'pidfd_open'),(os,'system')]:
   block=patch.object(obj,name,side_effect=AssertionError('process effects prohibited'));block.start();self.blocks.append(block)
  self.addCleanup(lambda:[x.stop()for x in reversed(self.blocks)])
  self.baseline=json.loads(zlib.decompress(base64.b64decode(SEMANTIC_BASELINE_B64)));self.delta,self.projection,self.base=m.semantic_delta(self.baseline)
 def denied(self,fn,*a):
  with self.assertRaises((ValueError,RuntimeError,KeyError,FileNotFoundError)):fn(*a)
 def fixture(self):
  # Complete semantic roster joined to synthetic physical observations, never runtime authority.
  physical=[]
  for n,row in enumerate(self.projection):
   physical.append({**{k:row[k]for k in('declaredPath','canonicalPath','kind','baseAllowedKey')},'pin':dict(path=row['declaredPath'],sha256=row['sha256'],bytes=row['bytes'],device=7,inode=10000+n,uid=os.geteuid(),mode=0o600,nlink=1),'ancestorLinks':[]})
  clr_candidates=[r['pin']for r in physical if r['kind']=='clrPE'];clr_candidates+= [r['pin']for r in physical if r['kind']=='existingExecutable'and '/shared/Microsoft.NETCore.App/10.0.12/'in r['declaredPath']and r['declaredPath'].endswith('.dll')][:22]
  # There are22 historical CLR paths already in existingExecutable. Choose their
  # exact semantic entries from inherited rows where possible; digest is explicitly mocked.
  if len(clr_candidates)<335:clr_candidates+= [r['pin']for r in physical if r['kind']=='existingExecutable'and r['pin']not in clr_candidates][:335-len(clr_candidates)]
  assert len(clr_candidates)==335
  registry=[copy.deepcopy(r['pin'])for r in physical]
  for row,pin in zip(physical,registry):
   if row['kind']=='existingExecutable'and row['baseAllowedKey']!=row['declaredPath']:pin['symlinkCustody']={'resolvedPath':row['baseAllowedKey']}
  clr_candidates=[next(x for x in registry if x['path']==pin['path'])for pin in clr_candidates]
  p=dict(preparationReady=True,mappingBaseline=copy.deepcopy(self.baseline),mappingDelta=copy.deepcopy(self.delta),executableMappingIdentities=dict(schema=m.SCHEMA,baseAllowed=copy.deepcopy(self.base),clrPinCount=335,rows=physical),clrPins=copy.deepcopy(clr_candidates),hostPins=[],originalDataPins=copy.deepcopy(registry),elfPins=[],pythonPins=[],authorityPins=[],nativeHost=m.HOST,engine=m.HISTORICAL_DATA+'/spring-headless',dataRoot=m.DATA,policy=dict(apphost=m.POLICY))
  engine=next(r['pin']for r in physical if r['declaredPath']==p['engine']);p['originalDataPins']=[x for x in p['originalDataPins']if x['path']!=p['engine']];p['authorityPins']=[copy.deepcopy(engine)]
  p['allowedExecutableMappings']={r['canonicalPath']:r['pin']['sha256']for r in physical};p['requiredHostMappings']=[m.HOST]+[x for x in p['allowedExecutableMappings']if pathlib.Path(x).name in('libcoreclr.so','libclrjit.so')]
  p['requiredEngineMappings']={x['role']:dict(path=x['row']['declaredPath'],role=x['role'],sha256=x['row']['sha256'])for x in self.delta['added']if x['role']in m.AI};p['requiredEngineMappings']['engine']=dict(path=p['engine'],role='engine',sha256=self.delta['retainedEngine']['row']['sha256'])
  retained=copy.deepcopy(sorted([r for r in physical if r['declaredPath']not in{x['row']['declaredPath']for x in self.delta['added']}],key=lambda r:r['declaredPath']));clr=copy.deepcopy(p['clrPins']);actual=m.semantic_digest
  def digest(value):
   if value==clr:return m.CLR_PINS_SHA
   if value==retained:return m.RETAINED_PHYSICAL_ROWS_SHA
   return actual(value)
  return p,digest
 def validate(self,p,digest):
  with patch.object(m,'semantic_digest',side_effect=digest):return m.validate_schema(p)
 def test_independent_golden_delta(self):
  self.assertEqual(m.semantic_digest(self.delta),'e90554a5a7ead26b9db6eb3d250dd732bba1677842051406cf4d192437971060');self.assertEqual(len(self.projection),458);self.assertEqual(len(self.base),145);self.assertEqual(sum(x['kind']=='clrPE'for x in self.projection),313)
 def test_complete_projection_and_retained_engine_authority(self):
  p,digest=self.fixture();self.assertEqual(len(self.validate(p,digest)),458);p['authorityPins']=[];self.denied(self.validate,p,digest)
 def test_missing_extra_duplicate_reordered_delta(self):
  p,digest=self.fixture()
  for change in('missing','extra','duplicate','reordered'):
   q=copy.deepcopy(p)
   if change=='missing':q['mappingDelta']['added'].pop()
   elif change=='extra':q['mappingDelta']['unexpected']=1
   elif change=='duplicate':q['mappingDelta']['added'].append(q['mappingDelta']['added'][0])
   else:q['mappingDelta']['added'].reverse()
   with self.subTest(change=change):self.denied(self.validate,q,digest)
 def test_role_path_hash_size_and_noncanonical_delta(self):
  p,digest=self.fixture()
  for field,value in [('role','engine'),('declaredPath','/old/AI'),('canonicalPath','/path/../alias'),('sha256','0'*64),('bytes',1)]:
   q=copy.deepcopy(p);entry=q['mappingDelta']['added'][0];entry[field if field=='role'else'row']=value if field=='role'else dict(entry['row'],**{field:value});self.denied(self.validate,q,digest)
 def test_baseline_replacement_and_count_only_refuse(self):
  p,digest=self.fixture()
  for change in('row','count','base'):
   q=copy.deepcopy(p)
   if change=='row':q['mappingBaseline']['rows'][0]['sha256']='0'*64
   elif change=='count':q['executableMappingIdentities']['rows'][-1]=q['executableMappingIdentities']['rows'][0]
   else:q['mappingBaseline']['baseAllowed']['extra']='a'*64
   self.denied(self.validate,q,digest)
 def test_unchanged_clr_and_guard_injection(self):
  p,digest=self.fixture();q=copy.deepcopy(p);q['clrPins'][0]['inode']+=1;self.denied(self.validate,q,digest)
  q=copy.deepcopy(p);q['mappingDelta']['callerGuard']='ignored';self.denied(self.validate,q,digest)
 def test_original_physical_and_ancestor_retention(self):
  p,digest=self.fixture()
  for field,value in [('inode',1),('device',1),('uid',-1),('mode',0o644),('nlink',2),('ancestorLinks',[{'unselected':True}])]:
   q=copy.deepcopy(p);row=next(r for r in q['executableMappingIdentities']['rows']if r['declaredPath']not in{x['row']['declaredPath']for x in self.delta['added']})
   if field=='ancestorLinks':row[field]=value
   else:row['pin'][field]=value
   self.denied(self.validate,q,digest)
 def test_ambiguous_pin_metadata_refuses(self):
  p,digest=self.fixture();p['authorityPins'].append(dict(p['originalDataPins'][0],inode=-1));self.denied(self.validate,p,digest)
 def test_new_role_path_and_full_pin_join(self):
  p,digest=self.fixture()
  for field in('nativeHost','dataRoot','engine'):
   q=copy.deepcopy(p);q[field]='/unselected';self.denied(self.validate,q,digest)
  q=copy.deepcopy(p);q['policy']['apphost']='/old/policy';self.denied(self.validate,q,digest)
  q=copy.deepcopy(p);row=next(x for x in q['executableMappingIdentities']['rows']if x['declaredPath']==m.POLICY);row['pin']['inode']+=1;self.denied(self.validate,q,digest)
 def test_missing_preparation_refuses(self):
  p,digest=self.fixture();p['preparationReady']=False;self.denied(self.validate,p,digest)
 def test_unknown_executable_or_clr_row_refuses(self):
  p,digest=self.fixture()
  for kind in('existingExecutable','clrPE'):
   q=copy.deepcopy(p);new=copy.deepcopy(q['executableMappingIdentities']['rows'][-1]);new['declaredPath']='/unknown';new['kind']=kind;q['executableMappingIdentities']['rows'].append(new);self.denied(self.validate,q,digest)
 def test_strict_json_duplicate_nonfinite_and_link(self):
  with tempfile.TemporaryDirectory()as d:
   path=pathlib.Path(d)/'profile';path.write_text('{"a":1,"a":2}');path.chmod(0o600);self.denied(m.load_profile,path)
   path.write_text('{"a":NaN}');self.denied(m.load_profile,path);path.write_text('{"a":1}');self.assertEqual(m.load_profile(path),{'a':1});link=pathlib.Path(d)/'link';link.symlink_to(path);self.denied(m.load_profile,link)
 def actual_row(self,path):
  st=path.lstat();pin=dict(path=str(path),sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=st.st_size,device=st.st_dev,inode=st.st_ino,uid=st.st_uid,mode=st.st_mode&0o777,nlink=st.st_nlink)
  return dict(declaredPath=str(path),canonicalPath=str(path),kind='existingExecutable',baseAllowedKey=str(path),pin=pin,ancestorLinks=m.ancestor_links(path))
 def physical_check(self,row):
  with patch.object(m,'validate_schema',return_value=[row]):return m.revalidate({},lambda:None)
 def test_real_fresh_inode_same_semantics_needs_actual_capture(self):
  with tempfile.TemporaryDirectory()as d:
   path=pathlib.Path(d)/'artifact';path.write_bytes(b'actual controlled source bytes');path.chmod(0o600);old=self.actual_row(path);self.physical_check(old);path.rename(path.with_name('old-held'));path.write_bytes(b'actual controlled source bytes');path.chmod(0o600);fresh=self.actual_row(path)
   self.assertEqual(m.semantic_row(old),m.semantic_row(fresh));self.assertNotEqual(old['pin']['inode'],fresh['pin']['inode']);self.denied(self.physical_check,old);self.physical_check(fresh)
 def test_real_physical_drift_not_removed_from_revalidate(self):
  with tempfile.TemporaryDirectory()as d:
   path=pathlib.Path(d)/'artifact';path.write_bytes(b'bytes');path.chmod(0o600);row=self.actual_row(path)
   for field,value in [('device',-1),('inode',-1),('uid',-1),('mode',0o644),('nlink',2),('sha256','0'*64)]:
    wrong=copy.deepcopy(row);wrong['pin'][field]=value;self.denied(self.physical_check,wrong)
   wrong=copy.deepcopy(row);wrong['ancestorLinks']=[{}];self.denied(self.physical_check,wrong);path.write_bytes(b'drift');self.denied(self.physical_check,row)
 def test_missing_selected_placement_cannot_revalidate(self):
  p,digest=self.fixture()
  with patch.object(m,'semantic_digest',side_effect=digest):self.denied(m.revalidate,p,lambda:None)
if __name__=='__main__':unittest.main()
